// Room "P3 kitchen" (interior designer's part): the kitchen is 3 x 2 cells (x58..60, z19..20), feet at y2. The front
// door (59,18) and the back door (58,21) both open onto a clear first cell, so (59,19) and (58,20) stay bare, and the
// only lane between them runs through (59,20). The stove runs down the east wall under the window pair, its fronts
// facing west into the room (the focal piece, both lit). The barrel counter sits on the west wall with a potted poppy
// on its lid. Nothing hangs over the doorways.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  const legend = {
    // feet level: x58 z19 is the barrel counter, x60 z19..20 the stove (smoker north, furnace south)
    "B": ["barrel", { facing: "up", open: "true" }],
    "S": ["smoker", { facing: "west", lit: "true" }],
    "F": ["furnace", { facing: "west", lit: "true" }],
    // the potted flower stands on the barrel lid (y3)
    "P": ["potted_poppy", {}],
    // a lantern hangs from the ceiling over the lane's far end (y4)
    "L": ["lantern", { hanging: "true" }],
  };
  // rows run along +x (58, 59, 60), successive rows along +z (19, 20); layer y2, then y3, then y4
  layers(g, [58, 2, 19], legend, [
    ["B.S", "..F"],
    ["P..", "..."],
    ["..L", "..."],
  ]);
}

